              "content": "<div style=\"position:relative;width:100%;overflow:hidden;padding-top:56.25%\"><iframe style=\"position:absolute;top:0;left:0;bottom:0;right:0;width:100%;height:100%;border:none\" allow=\"autoplay; fullscreen\" allowfullscreen src=\"https://videos.dyntube.com/iframes/9FqF1Vm5g0eUC8ComqAPxQ\" title=\"9. Apa Itu Bitcoin\"></iframe></div>"
